/** Returns the bundled image for a unit (by id, falling back to name). */
export function getUnitImage(unit: Pick<Unit, 'unitID' | 'Name'>): ImageSourcePropType {
  return unitImagesById[unit.unitID] ?? unitImagesByName[unit.Name];
}

/** True when every unit in the dataset has a bundled image. */
export const everyUnitHasImage = units.every((u) => unitImagesById[u.unitID] != null);
